create or replace function public.painel_cidades(de timestamptz, ate timestamptz) returns table ( cidade text, regiao text, pais text, visitantes bigint, aprovadas bigint, receita numeric ) language sql stable set search_path = '' as $$ with v as ( select geo_city as cidade, geo_region as regiao, geo_country as pais, count(*) as total from public.visitors where created_at >= de and created_at < ate and geo_city is not null group by 1, 2, 3 ), c as ( select geo_city as cidade, geo_region as regiao, geo_country as pais, count(*) as pedidos, coalesce(sum(value), 0) as receita from public.purchases where created_at >= de and created_at < ate and geo_city is not null and status = 'aprovada' group by 1, 2, 3 ) select coalesce(v.cidade, c.cidade), coalesce(v.regiao, c.regiao), coalesce(v.pais, c.pais), coalesce(v.total, 0), coalesce(c.pedidos, 0), coalesce(c.receita, 0) from v full outer join c on c.cidade = v.cidade and c.regiao is not distinct from v.regiao and c.pais is not distinct from v.pais order by 4 desc, 6 desc; $$;
create index if not exists visitors_geo_city_idx on public.visitors (created_at, geo_city); revoke all on function public.painel_cidades(timestamptz, timestamptz) from public, anon; grant execute on function public.painel_cidades(timestamptz, timestamptz) to authenticated; drop function if exists public.painel_cidades(timestamptz, timestamptz);
create or replace function public.painel_cidades( de timestamptz, ate timestamptz, quantos integer default 20 ) returns table ( cidade text, regiao text, pais text, visitantes bigint, aprovadas bigint, receita numeric ) language sql stable set search_path = '' as $$ with v as ( select geo_city as cidade, geo_region as regiao, geo_country as pais, count(*) as total from public.visitors where created_at >= de and created_at < ate and geo_city is not null group by 1, 2, 3 ), c as ( select geo_city as cidade, geo_region as regiao, geo_country as pais, count(*) as pedidos, coalesce(sum(value), 0) as receita from public.purchases where created_at >= de and created_at < ate and geo_city is not null and status = 'aprovada' group by 1, 2, 3 ) select coalesce(v.cidade, c.cidade), coalesce(v.regiao, c.regiao), coalesce(v.pais, c.pais), coalesce(v.total, 0), coalesce(c.pedidos, 0), coalesce(c.receita, 0) from v full outer join c on c.cidade = v.cidade and c.regiao is not distinct from v.regiao and c.pais is not distinct from v.pais order by 4 desc, 6 desc limit greatest(quantos, 1); $$;
revoke all on function public.painel_cidades(timestamptz, timestamptz, integer) from public, anon; grant execute on function public.painel_cidades(timestamptz, timestamptz, integer) to authenticated;
